export const code = async (inputs) => {
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key, vars) => {
    let s = String(texts[key] === undefined || texts[key] === null ? key : texts[key]);
    if (vars) Object.keys(vars).forEach((k) => { s = s.split('{' + k + '}').join(String(vars[k])); });
    return s;
  };
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  const decision = (inputs.decision && typeof inputs.decision === 'object') ? inputs.decision : {};
  const notifyKind = String(decision.notifyKind || 'none');
  const targets = [];
  if (notifyKind !== 'none') {
    const seen = {};
    arr(inputs.records).map(flat).filter((r) => (r.status || '') === 'registered').forEach((r) => {
      const id = r.telegram_id || '';
      if (id && !seen[id]) { seen[id] = true; targets.push(id); }
    });
  }
  const vars = Object.assign({}, decision.ownerVars || {}, { count: targets.length });
  const ownerText = t(String(decision.ownerKey || 'manage.chat.updated'), vars);
  return { targets: targets, count: targets.length, ownerText: ownerText, notifyText: String(decision.notifyText || '') };
};

export const code = async (inputs) => {
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key, vars) => {
    let s = String(texts[key] === undefined || texts[key] === null ? key : texts[key]);
    if (vars) Object.keys(vars).forEach((k) => { s = s.split('{' + k + '}').join(String(vars[k])); });
    return s;
  };
  const str = (v) => String(v === undefined || v === null ? '' : v).trim();
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);

  const title = str(inputs.title);
  const eventId = str(inputs.eventId);
  const staffTelegramId = str(inputs.staffTelegramId);
  // Список целей — 0 или 1 элемент. Уведомляем только тех, кого бот уже видел
  // (строка в users, DAT-1): отправка в неизвестный chat_id — заведомо
  // провальный вызов. Цикл по пустому списку не делает ни одной отправки,
  // поэтому ветка «человека нет в users» не требует отдельного ROUTER'а.
  const targets = (arr(inputs.userRows).length > 0 && staffTelegramId !== '') ? [staffTelegramId] : [];

  // Вердикт W49 (W50): кнопка — «Открыть сканер» на конкретное событие.
  // Исключение из «чекина нет в чате»: событие здесь известно.
  const base = str(inputs.miniappUrl).replace(/\/+$/, '');
  const scanUrl = eventId !== '' ? base + '/#/scan?event_id=' + encodeURIComponent(eventId) : '';

  return {
    targets: targets,
    text: t('manage.staff.notify', { title: title }),
    reply_markup: scanUrl !== '' ? { inline_keyboard: [[{ text: t('staff.accept.btn.scanner'), web_app: { url: scanUrl } }]] } : {}
  };
};

export const code = async (inputs) => {
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key, vars) => {
    let s = String(texts[key] === undefined || texts[key] === null ? key : texts[key]);
    if (vars) Object.keys(vars).forEach((k) => { s = s.split('{' + k + '}').join(String(vars[k])); });
    return s;
  };
  const str = (v) => String(v === undefined || v === null ? '' : v).trim();
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = { __recordId: String(rec && rec.id ? rec.id : '') };
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };

  const hmac = inputs.hmac || {};
  const telegramId = str(hmac.telegramId);
  const req = inputs.req || {};
  const action = str(req.action);
  const eventId = str(req.eventId);
  const staffTelegramId = str(req.staffTelegramId);
  const nowIso = new Date().toISOString();

  // Пустой ответ по умолчанию — все поля тела всегда присутствуют, чтобы
  // return_response не ссылался на несуществующее (тот же приём, что в step_7).
  const respond = (outcome, httpStatus, body) => Object.assign({
    outcome: outcome, httpStatus: httpStatus,
    ok: false, error: '', text: '', fields: {}, event: {}, eventId: eventId,
    title: '', staff: [],
    recordId: '-', newStaffId: '', grantedBy: '', grantedAt: '', revokedAt: ''
  }, body);

  const forbidden = () => respond('error', 403, { error: 'forbidden', text: t('manage.err.forbidden') });

  // --- defense in depth: те же проверки, что в step_7 -------------------------
  // Гейт уже пройден step_7, но отбор повторяется по полям записи (Q25):
  // «не staff», «чужой чаптер» и «нет события» отвечают одинаково.
  const staffRow = arr(inputs.staff).map(flat).filter((r) => str(r.telegram_id) === telegramId)[0] || null;
  if (!telegramId || !staffRow) return forbidden();
  const staffChapter = str(staffRow.chapter_id);
  const canAccess = (chapterId) => staffChapter === '' || staffChapter === str(chapterId);
  const ev = arr(inputs.event).map(flat).filter((r) => str(r.id) === eventId)[0] || null;
  if (eventId === '-' || eventId === '' || !ev || !canAccess(ev.chapter_id)) return forbidden();
  const title = str(ev.title);

  // --- текущий список: активные строки по полям, а не по позиции выборки ------
  const rows = arr(inputs.staffRecords).map(flat).filter((r) => str(r.event_id) === eventId);
  const active = rows.filter((r) => str(r.revoked_at) === '');
  const isActive = (id) => active.some((r) => str(r.telegram_id) === id);

  // Строку списка собирает сервер и отдаёт готовой: в словаре SPA интерполяции
  // нет, а дата нужна ташкентская (OWN-3). Имена — join с users по telegram_id
  // (W54: отмена решения W36 «имён нет намеренно»; как participants/search);
  // кого нет в users — fallback на item без имени.
  const DATE_FMT = new Intl.DateTimeFormat('ru-RU', { timeZone: 'Asia/Tashkent', day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
  const fmt = (iso) => {
    const s = str(iso);
    if (s === '') return '—';
    const ms = Date.parse(/[Zz]$/.test(s) || /[+-][0-9]{2}:?[0-9]{2}$/.test(s) ? s : s + 'Z');
    return isFinite(ms) ? DATE_FMT.format(new Date(ms)) : '—';
  };
  const item = (id, grantedAt) => t('manage.staff.item', { id: id, when: fmt(grantedAt) });
  const usersById = {};
  arr(inputs.userRows).map(flat).forEach((u) => {
    const id = str(u.telegram_id);
    if (id !== '' && usersById[id] === undefined) {
      const nm = (str(u.first_name) + ' ' + str(u.last_name)).trim();
      usersById[id] = { name: nm, username: str(u.username) };
    }
  });
  const shape = (id, grantedAt) => {
    const w = usersById[id] || { name: '', username: '' };
    const since = fmt(grantedAt);
    return {
      telegram_id: id,
      item: item(id, grantedAt),
      name: w.name,
      username: w.username,
      sub: w.username !== '' ? w.username + ' · ' + t('manage.staff.since', { when: since }) : ''
    };
  };
  const listOut = (extraIds) => active
    .map((r) => shape(str(r.telegram_id), r.granted_at))
    .concat((extraIds || []).map((id) => shape(id, nowIso)));

  if (action === 'staff_list') {
    return respond('list', 200, { ok: true, title: title, staff: listOut() });
  }

  // --- валидация telegram_id --------------------------------------------------
  // Только цифры 8–16: telegram_id — единственный ключ (DAT-1), username не годится.
  if (!/^[0-9]{8,16}$/.test(staffTelegramId)) {
    return respond('error', 422, {
      error: 'validation', text: t('manage.err.validation'),
      fields: { telegram_id: 'manage.err.bad_telegram_id' },
      title: title, staff: listOut()
    });
  }

  if (action === 'staff_add') {
    // Идемпотентность добавления (ADR-0003): активная строка уже есть — вторую
    // не создаём, отвечаем тем же списком. Гонка двух одновременных добавлений
    // остаётся возможной ценой ADR-0003: уникальности в БД нет.
    if (isActive(staffTelegramId)) {
      return respond('list', 200, { ok: true, text: t('manage.staff.already'), title: title, staff: listOut() });
    }
    return respond('add', 200, {
      ok: true,
      text: t('manage.staff.added'),
      newStaffId: staffTelegramId,
      grantedBy: telegramId,
      grantedAt: nowIso,
      title: title,
      staff: listOut([staffTelegramId])
    });
  }

  if (action === 'staff_remove') {
    const row = active.filter((r) => str(r.telegram_id) === staffTelegramId)[0] || null;
    // Отзывать нечего — не ошибка: повторный отзыв идемпотентен (ADR-0003),
    // отвечаем текущим списком и текстом «активных прав нет».
    if (!row) {
      return respond('list', 200, { ok: true, text: t('manage.staff.gone'), title: title, staff: listOut() });
    }
    const recordId = str(row.__recordId);
    if (recordId === '') return respond('error', 400, { error: 'bad_request', text: t('manage.err.server'), title: title, staff: listOut() });
    return respond('remove', 200, {
      ok: true,
      text: t('manage.staff.revoked'),
      recordId: recordId,
      revokedAt: nowIso,
      title: title,
      staff: listOut().filter((r) => r.telegram_id !== staffTelegramId)
    });
  }

  return respond('error', 400, { error: 'bad_request', text: t('manage.err.server'), title: title, staff: listOut() });
};

export const code = async (inputs) => {
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  const str = (v) => String(v === undefined || v === null ? '' : v).trim();
  const parse = (s) => { if (!s) return NaN; return Date.parse(/[Zz]$/.test(s) || /[+-][0-9]{2}:?[0-9]{2}$/.test(s) ? s : s + 'Z'); };
  const me = str(inputs.me);

  // Отбор по chapter_id уже сделан фильтром чтения (step_31); здесь только
  // форма ответа и порядок. Записи без id не показываем.
  const rows = arr(inputs.records).map(flat)
    .filter((r) => str(r.id) !== '')
    .map((r) => {
      const isAuthor = str(r.staff_id) === me;
      const out = {
        id: str(r.id),
        title: str(r.title),
        starts_at: str(r.starts_at),
        status: str(r.status),
        // W74: сырой дедлайн регистрации — список решает, показать ли бейдж
        // «Регистрация закрыта» (published + дедлайн в прошлом + начало в будущем).
        reg_deadline_at: str(r.reg_deadline_at),
        // isAuthor — метка «кто создал» на карточке (staff_id, ADR-0024 п. 3)
        isAuthor: isAuthor
      };
      // W42: недавние места визарда — только свои события и только с адресом;
      // чужие адреса в ответ списка не кладём (их видно лишь в правке события).
      if (isAuthor && str(r.address) !== '') {
        out.address = str(r.address);
        out.lat = str(r.lat);
        out.lon = str(r.lon);
      }
      return out;
    });
  // Сначала ближайшие будущие (по возрастанию), затем прошедшие (по убыванию):
  // организатору нужно ближайшее событие под рукой, а не самое старое.
  const now = Date.now();
  const isFuture = (x) => { const ms = parse(x.starts_at); return isFinite(ms) && ms >= now; };
  const key = (x) => { const ms = parse(x.starts_at); return isFinite(ms) ? ms : 0; };
  const upcoming = rows.filter(isFuture).sort((a, b) => key(a) - key(b));
  const past = rows.filter((x) => !isFuture(x)).sort((a, b) => key(b) - key(a));
  const events = upcoming.concat(past);

  return { ok: true, events: events, count: events.length, error: '', text: '', eventId: '' };
};

export const code = async (inputs) => {
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key) => String(texts[key] === undefined || texts[key] === null ? key : texts[key]);
  const fail = () => ({
    httpStatus: 422, ok: false,
    lat: '', lon: '', address: '',
    error: 'validation',
    text: t('manage.geo.org_fail'),
    fields: { geo: 'manage.geo.org_fail' },
  });
  // Форма вывода http qadam зависит от исхода (ARCHITECTURE): 2xx — плоская
  // { status, headers, body }, 4xx/5xx при continue_all — { response: { status, body } }.
  const resp = (inputs.resp && typeof inputs.resp === 'object') ? inputs.resp : {};
  const flat = (resp.body !== undefined || resp.status !== undefined)
    ? resp
    : ((resp.response && typeof resp.response === 'object') ? resp.response : {});
  let doc = flat.body;
  if (typeof doc === 'string') {
    if (!doc) return fail();
    try { doc = JSON.parse(doc); } catch (e) { return fail(); }
  }
  if (!doc || typeof doc !== 'object') return fail();
  const coll = doc.response && doc.response.GeoObjectCollection ? doc.response.GeoObjectCollection : null;
  const members = coll && Array.isArray(coll.featureMember) ? coll.featureMember : [];
  const obj = members.length && members[0] && members[0].GeoObject ? members[0].GeoObject : null;
  const pos = obj && obj.Point && typeof obj.Point.pos === 'string' ? obj.Point.pos.trim() : '';
  // Геокодер отдаёт pos как «долгота широта» — порядок фиксирован документацией.
  const pm = /^(-?\d+(?:\.\d+)?)\s+(-?\d+(?:\.\d+)?)$/.exec(pos);
  if (!pm) return fail();
  const lon = Number(pm[1]), lat = Number(pm[2]);
  if (!isFinite(lat) || !isFinite(lon) || Math.abs(lat) > 90 || Math.abs(lon) > 180) return fail();
  const meta = (obj.metaDataProperty && obj.metaDataProperty.GeocoderMetaData) ? obj.metaDataProperty.GeocoderMetaData : {};
  const rawAddr = (meta.Address && typeof meta.Address.formatted === 'string' && meta.Address.formatted)
    ? meta.Address.formatted
    : (typeof meta.text === 'string' ? meta.text : '');
  // Яндекс дублирует компоненты («Узбекистан, Ташкент, Ташкент, BeeLab») —
  // подряд идущие одинаковые куски схлопываем.
  const parts = String(rawAddr).split(',').map((s) => s.trim()).filter((s) => s !== '');
  const addr = parts.filter((s, i) => i === 0 || s.toLowerCase() !== parts[i - 1].toLowerCase()).join(', ');
  return {
    httpStatus: 200, ok: true,
    lat: String(Math.round(lat * 1e6) / 1e6),
    lon: String(Math.round(lon * 1e6) / 1e6),
    address: String(addr).slice(0, 300),
    error: '', text: '', fields: {},
  };
};

export const code = async (inputs) => {
  // Орг-ссылка Яндекс.Карт («Поделиться» из приложения): вырезаем только
  // числовой oid. URL Геокодера фиксирован в http-шаге, из входной строки
  // в запрос уходит лишь oid — это не прокси для произвольных URL (Q55).
  // Формы: https://yandex.com/maps/org/beelab/34279609643?si=…
  //        https://yandex.ru/maps/org/1234567/
  // Короткие yandex.ru/maps/-/… не поддержаны: в них нет oid (Q55).
  const link = String(inputs.link === undefined || inputs.link === null ? '' : inputs.link).trim();
  const m = /^https?:\/\/(?:[a-z0-9-]+\.)*yandex\.[a-z.]{2,6}\/maps\/org\/(?:[^/?#]+\/)?(\d{1,20})(?:[/?#]|$)/i.exec(link);
  const oid = m ? m[1] : '';
  return {
    oid: oid,
    // Значение, которое принимает Геокодер в параметре uri (форма из
    // ответа Геосаджеста). Пустой uri даёт 400 — разбор ответа превратит
    // это в общий отказ `manage.geo.org_fail`.
    uri: oid ? ('ymapsbm1://org?oid=' + oid) : '',
    ok: oid !== '',
  };
};

export const code = async (inputs) => {
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key, vars) => {
    let s = String(texts[key] === undefined || texts[key] === null ? key : texts[key]);
    if (vars) Object.keys(vars).forEach((k) => { s = s.split('{' + k + '}').join(String(vars[k])); });
    return s;
  };
  const str = (v) => String(v === undefined || v === null ? '' : v).trim();
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };

  const hmac = inputs.hmac || {};
  const telegramId = str(hmac.telegramId);
  const req = inputs.req || {};
  const eventId = str(req.eventId);

  // Пустой ответ по умолчанию — все поля тела всегда присутствуют, чтобы
  // return_response не ссылался на несуществующее (тот же приём, что в
  // step_7/step_20).
  const respond = (outcome, httpStatus, body) => Object.assign({
    outcome: outcome, httpStatus: httpStatus,
    ok: false, error: '', text: '', fields: {}, event: {}, eventId: eventId,
    title: '', candidates: [], count: 0
  }, body);

  const forbidden = () => respond('error', 403, { error: 'forbidden', text: t('manage.err.forbidden') });

  // --- defense in depth: те же проверки, что в step_7/step_20 (Q25) -----------
  // Гейт уже пройден step_7, но отбор повторяется по полям записи:
  // «не staff», «чужой чаптер» и «нет события» отвечают одинаково.
  const staffRow = arr(inputs.staff).map(flat).filter((r) => str(r.telegram_id) === telegramId)[0] || null;
  if (!telegramId || !staffRow) return forbidden();
  const staffChapter = str(staffRow.chapter_id);
  const canAccess = (chapterId) => staffChapter === '' || staffChapter === str(chapterId);
  const ev = arr(inputs.event).map(flat).filter((r) => str(r.id) === eventId)[0] || null;
  if (eventId === '-' || eventId === '' || !ev || !canAccess(ev.chapter_id)) return forbidden();
  const title = str(ev.title);

  // --- запрос: минимум 2 символа (решение W44) --------------------------------
  // Короткий/пустой запрос — пустой список, а не вся база: без запроса базу
  // не светим. Фильтры Tables по подстроке не умеют (Q15), поэтому сравнение
  // здесь, в коде, а не в чтении.
  const q = str(req.query).replace(/^@/, '').toLowerCase();
  if (q.length < 2) return respond('done', 200, { ok: true, title: title, candidates: [], count: 0 });

  // --- кандидаты: участники события + staff чаптера (Q51) ----------------------
  // Участники — все telegram_id из registrations события (включая отменённые:
  // человек остался известен боту, как в прототипе data.js). Staff — строки
  // staff этого чаптера плюс глобальные (chapter_id=''). Действующие
  // контролёры события исключаются (их добавлять не надо — они уже).
  const pool = {};
  arr(inputs.regRows).map(flat).forEach((r) => {
    if (str(r.event_id) === eventId && str(r.telegram_id) !== '') pool[str(r.telegram_id)] = true;
  });
  const chapterId = str(ev.chapter_id);
  arr(inputs.staffRows).map(flat).forEach((r) => {
    const c = str(r.chapter_id);
    if ((c === '' || chapterId === '' || c === chapterId) && str(r.telegram_id) !== '') pool[str(r.telegram_id)] = true;
  });
  const active = {};
  arr(inputs.controllerRows).map(flat).forEach((r) => {
    if (str(r.event_id) === eventId && str(r.revoked_at) === '' && str(r.telegram_id) !== '') active[str(r.telegram_id)] = true;
  });

  // --- join к users и совпадение ----------------------------------------------
  // Имя и username — только подписи для поиска (DAT-1): решение и запись идут
  // по telegram_id, username ключом не становится. Кого нет в users — показать
  // нечего: такого человека добавить нельзя (W55: ввод по ID убран), он должен
  // хотя бы раз открыть бота.
  const usersById = {};
  arr(inputs.userRows).map(flat).forEach((r) => {
    const id = str(r.telegram_id);
    if (id !== '' && !usersById[id]) usersById[id] = r;
  });
  const out = [];
  Object.keys(pool).forEach((id) => {
    if (active[id]) return;
    const u = usersById[id];
    if (!u) return;
    const name = (str(u.first_name) + ' ' + str(u.last_name)).trim();
    const username = str(u.username).replace(/^@/, '');
    if (name === '' && username === '') return;
    const hay = (name + ' ' + username).toLowerCase();
    if (hay.indexOf(q) < 0) return;
    out.push({ telegram_id: id, name: name, username: username });
  });
  out.sort((a, b) => (a.name || a.username) < (b.name || b.username) ? -1 : 1);
  const top = out.slice(0, 20);
  return respond('done', 200, { ok: true, title: title, candidates: top, count: top.length });
};

export const code = async (inputs) => {
  // W13: участники события (OWN-7) + строки CSV/JSON для экспорта (OWN-8).
  // Тексты — во входе `texts` (ADR-0014), источник — i18n/ru.json.
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key, vars) => {
    let s = String(texts[key] === undefined || texts[key] === null ? key : texts[key]);
    if (vars) Object.keys(vars).forEach((k) => { s = s.split('{' + k + '}').join(String(vars[k])); });
    return s;
  };
  const str = (v) => String(v === undefined || v === null ? '' : v).trim();
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };

  const hmac = inputs.hmac || {};
  const telegramId = str(hmac.telegramId);
  const req = inputs.req || {};
  const eventId = str(req.eventId);

  // Пустой ответ по умолчанию — все поля тела всегда присутствуют, чтобы
  // return_response не ссылался на несуществующее (тот же приём, что в
  // step_7/step_20/step_42).
  const respond = (outcome, httpStatus, body) => Object.assign({
    outcome: outcome, httpStatus: httpStatus,
    ok: false, error: '', text: '', fields: {}, event: {}, eventId: eventId,
    title: '', counters: { registered: 0, checked_in: 0, cancelled: 0, all_consent: 0 },
    rows: [], count: 0, csv: '', json: '[]'
  }, body);

  const forbidden = () => respond('error', 403, { error: 'forbidden', text: t('manage.err.forbidden') });

  // --- defense in depth: та же граница, что `load` (Q25) ----------------------
  // Гейт уже пройден step_7, но отбор повторяется по полям записи, а не как
  // непустота выборки: «не staff», «чужой чаптер» и «нет события» отвечают
  // одинаково — одним 403.
  const staffRow = arr(inputs.staff).map(flat).filter((r) => str(r.telegram_id) === telegramId)[0] || null;
  if (!telegramId || !staffRow) return forbidden();
  const staffChapter = str(staffRow.chapter_id);
  const canAccess = (chapterId) => staffChapter === '' || staffChapter === str(chapterId);
  const ev = arr(inputs.event).map(flat).filter((r) => str(r.id) === eventId)[0] || null;
  if (eventId === '-' || eventId === '' || !ev || !canAccess(ev.chapter_id)) return forbidden();
  const title = str(ev.title);

  // --- схлопывание дублей по telegram_id (DATA-MODEL, IDM-1/IDM-2) ------------
  // Уникальности в БД нет (ADR-0003): одна пара (event_id, telegram_id) может
  // дать несколько строк. Статус берёт самая ранняя строка по registered_at —
  // эталон fn-find-registration (с ним же сверяется чекин, расходиться нельзя);
  // пришёл = непустой checked_in_at хоть в одной строке (IDM-2), показывается
  // самое раннее время.
  const parseIso = (s) => {
    if (!s) return NaN;
    return Date.parse(/[Zz]$/.test(s) || /[+-][0-9]{2}:?[0-9]{2}$/.test(s) ? s : s + 'Z');
  };
  const rows = arr(inputs.regRows).map(flat)
    .filter((r) => str(r.event_id) === eventId && str(r.telegram_id) !== '');
  const ratMs = (r) => parseIso(str(r.registered_at));
  rows.sort((a, b) => {
    const x = ratMs(a), y = ratMs(b);
    if (isFinite(x) && isFinite(y)) return x - y;
    if (isFinite(x)) return -1;
    if (isFinite(y)) return 1;
    return 0;
  });
  const byId = {};
  rows.forEach((r) => {
    const id = str(r.telegram_id);
    if (!byId[id]) byId[id] = { status: 'registered', checked_in_at: '', seen: false };
    const cur = byId[id];
    if (!cur.seen) {
      cur.status = str(r.status) === 'cancelled' ? 'cancelled' : 'registered';
      cur.seen = true;
    }
    const cin = str(r.checked_in_at);
    if (cin !== '') {
      const ms = parseIso(cin), curMs = parseIso(cur.checked_in_at);
      if (cur.checked_in_at === '' || (isFinite(ms) && (!isFinite(curMs) || ms < curMs))) cur.checked_in_at = cin;
    }
  });

  // --- имена из users (DAT-1: только подписи, решение — по telegram_id) -------
  // Кого нет в users — показать нечего: имя заменяет сам telegram_id, строка
  // не теряется (экспорт обязан сходиться со счётчиками).
  const usersById = {};
  arr(inputs.userRows).map(flat).forEach((r) => {
    const id = str(r.telegram_id);
    if (id !== '' && !usersById[id]) usersById[id] = r;
  });
  const personName = (id) => {
    const u = usersById[id];
    if (!u) return id;
    const name = (str(u.first_name) + ' ' + str(u.last_name)).trim();
    if (name !== '') return name;
    const username = str(u.username).replace(/^@/, '');
    if (username !== '') return '@' + username;
    return id;
  };

  // --- даты — Asia/Tashkent словами (OWN-3) -----------------------------------
  // Формат фиксирован строкой «DD.MM.YYYY HH:mm»: читается в RU-Excel как
  // дата, в JSON — однозначен. Строится из частей (formatToParts), а не
  // готовой строкой Intl — разделители не зависят от версии ICU.
  const dtf = new Intl.DateTimeFormat('ru-RU', {
    timeZone: 'Asia/Tashkent',
    day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23'
  });
  const fmtTashkent = (iso) => {
    const ms = parseIso(iso);
    if (!isFinite(ms)) return '';
    const parts = {};
    dtf.formatToParts(new Date(ms)).forEach((p) => { parts[p.type] = p.value; });
    return parts.day + '.' + parts.month + '.' + parts.year + ' ' + parts.hour + ':' + parts.minute;
  };

  // --- строки: сначала пришедшие, затем зарегистрированные, затем отмены -----
  // Внутри группы — по имени (простое сравнение строк, без localeCompare:
  // его порядок зависит от ICU рантайма). Тот же порядок — в CSV и JSON.
  const groupOf = (p) => (p.checked_in_at !== '' ? 0 : (p.status === 'registered' ? 1 : 2));
  const shaped = Object.keys(byId).map((id) => ({
    telegram_id: id,
    name: personName(id),
    status: byId[id].status,
    checked_in_at: fmtTashkent(byId[id].checked_in_at)
  }));
  shaped.sort((a, b) => {
    const g = groupOf(a) - groupOf(b);
    if (g !== 0) return g;
    if (a.name < b.name) return -1;
    if (a.name > b.name) return 1;
    return a.telegram_id < b.telegram_id ? -1 : 1;
  });

  // --- счётчики — по УНИКАЛЬНЫМ telegram_id, не строкам (DATA-MODEL) ----------
  // registered включает пришедших (статус у них registered) — как в эталоне
  // (48 ≥ 31) и формулах DATA-MODEL: зарегистрировано = status=registered;
  // пришло = checked_in_at непусто; отменило = status=cancelled.
  const counters = { registered: 0, checked_in: 0, cancelled: 0, all_consent: 0 };
  shaped.forEach((p) => {
    if (p.status === 'registered') counters.registered += 1;
    else counters.cancelled += 1;
    if (p.checked_in_at !== '') counters.checked_in += 1;
  });

  // --- W68 (#120): «подписчики анонсов» (all_consent) -------------------------
  // Глобальный сегмент, не по событию: те же правила, что в bcast-step/bcast-run
  // (consent_marketing = true, кроме заблокировавших бота), по уникальным
  // telegram_id. Счётчик для таба «Рассылка» в Mini App; событие ему не нужно.
  const allConsent = {};
  arr(inputs.consentRows).map(flat).forEach((u) => {
    const id = str(u.telegram_id);
    if (id === '' || str(u.consent_marketing) !== 'true' || str(u.blocked_bot) === 'true') return;
    allConsent[id] = true;
  });
  counters.all_consent = Object.keys(allConsent).length;

  // --- экспорт: собирает сервер одной строкой (OWN-8) -------------------------
  // Файл строит сервер, а не SPA: экранирование и даты в одном месте, рядом
  // со счётчиками — расхождения «на экране одно, в файле другое» нет.
  // Статус — русским текстом (тот же словарь, что экран: myreg.status.*);
  // пришедший показывается «был на событии», как в эталоне.
  const statusText = (p) => {
    if (p.checked_in_at !== '') return t('myreg.status.checked_in');
    if (p.status === 'cancelled') return t('myreg.status.cancelled');
    return t('myreg.status.registered');
  };
  // CSV-инъекция: значение, начинающееся с = + - @, получает префикс '
  // (запятая не входит: разделитель — ';' под RU-Excel). Кавычки удваиваются,
  // каждое поле — в кавычках: один инвариант на все поля, без исключений.
  const csvEsc = (v) => {
    let s = String(v);
    if (/^[=+\-@]/.test(s)) s = "'" + s;
    return '"' + s.replace(/"/g, '""') + '"';
  };
  const header = [t('manage.parts.col_telegram_id'), t('manage.parts.col_name'), t('manage.parts.col_status'), t('manage.parts.col_checked_in')].map(csvEsc).join(';');
  const csvBody = shaped.map((p) => [p.telegram_id, p.name, statusText(p), p.checked_in_at].map(csvEsc).join(';')).join('\n');
  // BOM — первый символ строки: любой потребитель, сохранивший её как есть,
  // получает файл с целой кириллицей в Excel. JSON — без BOM (валидность).
  const csv = '﻿' + header + (csvBody ? '\n' + csvBody : '');
  const json = JSON.stringify({
    event: { id: eventId, title: title },
    exported_at: fmtTashkent(new Date(Date.now()).toISOString()),
    counters: counters,
    rows: shaped.map((p) => ({ telegram_id: p.telegram_id, name: p.name, status: statusText(p), checked_in_at: p.checked_in_at }))
  }, null, 2);

  return respond('done', 200, {
    ok: true, title: title,
    counters: counters, rows: shaped, count: shaped.length,
    csv: csv, json: json
  });
};

