export const code = async (inputs) => {
  // W66 (OWN-4.1): решение об удалении. Права/существование события проверены
  // в step_7. Здесь — серверная проверка «ноль регистраций» (Q25) и связанных
  // строк; само удаление — отдельный tables-шаг в ветке «canDelete» (гоча 15:
  // continueOnFailure не гейтит, гейт — ROUTER).
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key) => String(texts[key] === undefined || texts[key] === null ? key : texts[key]);
  const str = (v) => String(v === undefined || v === null ? '' : v).trim();
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);

  const ev = inputs.ev || {};
  const eventId = str(ev.id);
  const status = str(ev.status);
  const recordId = str(ev.recordId);
  const regs = arr(inputs.regs);
  const staff = arr(inputs.staff);

  const deny = (reason, key, httpStatus) => ({
    ok: false, canDelete: false, deleted: false, reason: reason,
    recordId: '', eventId: eventId, httpStatus: httpStatus, text: t(key)
  });

  // Порядок проверок важен: «есть регистрации» отвечает раньше прочих отказов,
  // чтобы опубликованное событие с участниками получало has_registrations
  // (а не not_draft) — так страница выбирает правильную кнопку.
  if (regs.length > 0) return deny('has_registrations', 'manage.delete.has_registrations', 409);
  // Part 1: удаляются только черновики (SPEC OWN-4.1); опубликованное с нулём
  // регистраций — Part 2 (#118).
  if (status !== 'draft') return deny('not_draft', 'manage.delete.not_draft', 409);
  // Связанные строки блокируют удаление, а не чистятся каскадом (OWN-4.1).
  if (staff.length > 0) return deny('has_staff', 'manage.delete.has_staff', 409);
  if (!recordId) return deny('not_found', 'manage.err.server', 500);

  return {
    ok: true, canDelete: true, deleted: false, reason: '',
    recordId: recordId, eventId: eventId, httpStatus: 200, text: t('manage.delete.done')
  };
};

