    Object.keys(cells).forEach((fid) => {
      const c = cells[fid]; if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    // W66: внутренний id записи (нужен tables-delete-record, гоча 18) — отдельным
    // ключом, чтобы не путать с бизнес-полем `id` из ячеек.
