  // в SPA) и отдаётся только для опубликованного события — draft невидим.
  const inviteFor = (eid, status) => (botUsername && status === 'published' && eid) ? ('https://t.me/' + botUsername + '?start=e' + eid) : '';
  const now = Date.now();
  const nowIso = new Date(now).toISOString();

  // Пустой ответ по умолчанию — все поля тела всегда присутствуют, чтобы
  // return_response не ссылался на несуществующее.
  const respond = (outcome, httpStatus, body) => Object.assign({
    outcome: outcome, httpStatus: httpStatus,
    ok: false, error: '', text: '', fields: {}, event: {}, eventId: '',
    // запись
